// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory tos, uint256 v) public {
        vm.assume(tos.length > 0);
        vm.assume(caddress != address(0));

        // Deploy a mock to capture the selector used
        address mock = address(new Mock());

        // Replace caddress with mock to observe the call
        c.transfer(from, mock, tos, v);

        // The mapping will store the selector, then we check it
        bytes4 storedSelector = Mock(mock).lastSelector();
        assertTrue(storedSelector == bytes4(keccak256("transferFrom(address,address,uint256)")), "Selector should be transferFrom");
    }
}

contract Mock {
    bytes4 public lastSelector;

    fallback(bytes calldata data) external returns (bytes memory) {
        if (data.length >= 4) {
            lastSelector = bytes4(data[:4]);
        }
        return "";
    }
}

